SELECT ?uri (COUNT(?award) AS ?awardCount) WHERE {
  ?uri <http://dbpedia.org/property/awards> ?award .
} GROUP BY ?uri ORDER BY DESC(?awardCount) LIMIT 1

SELECT DISTINCT ?uri WHERE {
  ?uri <http://dbpedia.org/ontology/award> ?award .
}
GROUP BY ?uri
ORDER BY DESC(COUNT(?award))
LIMIT 1

SELECT DISTINCT ?artist (COUNT(DISTINCT ?album) AS ?albumCount) WHERE {
  ?album <http://dbpedia.org/ontology/musicalArtist> ?artist .
} GROUP BY ?artist ORDER BY DESC(?albumCount) LIMIT 5

SELECT DISTINCT ?artist (COUNT(DISTINCT ?album) AS ?albumCount) WHERE {
  ?album <http://dbpedia.org/ontology/artist> ?artist .
} GROUP BY ?artist ORDER BY DESC(?albumCount) LIMIT 5

SELECT ?kingdom (COUNT(?species) AS ?count) WHERE {
  ?species <http://dbpedia.org/ontology/conservationStatus> ?status .
  FILTER(REGEX(STR(?status), "EN", "i"))
  ?species <http://dbpedia.org/ontology/kingdom> ?kingdom .
} GROUP BY ?kingdom ORDER BY DESC(?count) LIMIT 3

SELECT DISTINCT ?kingdom (COUNT(DISTINCT ?species) AS ?count) WHERE {
  ?species <http://dbpedia.org/ontology/conservationStatus> ?status .
  FILTER(REGEX(STR(?status), "EN", "i"))
  ?species <http://dbpedia.org/ontology/kingdom> ?kingdom .
} GROUP BY ?kingdom ORDER BY DESC(?count) LIMIT 3

SELECT DISTINCT ?uri ?date WHERE {
  ?uri <http://dbpedia.org/ontology/author> <http://dbpedia.org/resource/Mark_Twain> .
  ?uri <http://dbpedia.org/ontology/publicationDate> ?date .
} ORDER BY ASC(?date) LIMIT 10

SELECT DISTINCT ?uri ?date WHERE {
  {
    ?uri <http://dbpedia.org/ontology/author> <http://dbpedia.org/resource/Mark_Twain> .
  } UNION {
    ?uri <http://dbpedia.org/ontology/writer> <http://dbpedia.org/resource/Mark_Twain> .
  }
  ?uri <http://dbpedia.org/ontology/releaseDate> ?date .
} ORDER BY ASC(?date) LIMIT 10

SELECT DISTINCT ?alliance WHERE {
  ?airline <http://dbpedia.org/property/alliance> ?alliance .
}
GROUP BY ?alliance
ORDER BY DESC(COUNT(?airline))
LIMIT 1

SELECT DISTINCT ?alliance WHERE {
  ?airline <http://dbpedia.org/property/alliances> ?alliance .
}
GROUP BY ?alliance
ORDER BY DESC(COUNT(?airline))
LIMIT 1

SELECT DISTINCT COUNT(?river) WHERE {
  { ?structure <http://dbpedia.org/property/designer> <http://dbpedia.org/resource/Gustave_Eiffel> }
  UNION
  { ?structure <http://dbpedia.org/property/architect> <http://dbpedia.org/resource/Gustave_Eiffel> }
  { ?structure <http://dbpedia.org/ontology/crosses> ?river }
  UNION
  { ?structure <http://dbpedia.org/property/crosses> ?river }
